window.docContents[180].resolve({"/rules/PL1003/#PL1003-example":{"contents":"\n\nThe client file is unchanged. The dependency supplies a proof of the same reflexivity statement instead of declaring it as an axiom.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1003: Unknown transitive axioms are forbidden","header":"Checked example","id":"/rules/PL1003/#PL1003-example"},"/rules/PL2002/#PL2002-example":{"contents":"\n\nThe correction removes the unknown manifest key without changing the selected source, profile or execution requirement.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2002: Configuration must classify the complete Lake surface","header":"Checked example","id":"/rules/PL2002/#PL2002-example"},"/rules/PL3001/#PL3001-example":{"contents":"\n\nThe correction removes a no-effect custom evaluator command that prevents history authentication; the reference, replacement and correspondence theorem are unchanged.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL3001: Execution closure must have no unresolved paths","header":"Checked example","id":"/rules/PL3001/#PL3001-example"}});